using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DefaultEffectAsDescriptionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/DefaultEffectAsDescriptionCustomDescription", order = 0)]
public class DefaultEffectAsDescriptionCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private bool useAmount;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		return (battleAction as DefaultEffectAction).Effect.GetEffectDescription(useAmount ? GetFinalAmountWithoutEquation(amountModified) : EffectsValues.NO_VALUE);
	}
}
